#!/usr/bin/env bash
#
# Patches the GENERATED native project for the device gate (Z12-35). Run by the
# shared build scripts as their QA_POST_PREBUILD_HOOK, right after `expo prebuild`:
#
#   scripts/qa/device/patch-native.sh ios <apps/mobile/ios>
#   scripts/qa/device/patch-native.sh android <apps/mobile/android>
#
# Only apps/mobile/ios and apps/mobile/android are touched, both git-ignored and
# regenerated by every prebuild. app.config.js, the config plugins and the native
# dependencies are NOT changed: native changes in W12 belong to Z12-57 alone. Each
# patch is idempotent and prints what it found before it changed anything, so the
# job log records whether the stock project already allowed it.
#
# iOS
#   1. App Transport Security: NSAppTransportSecurity.NSAllowsLocalNetworking = true,
#      so the Release app may call http://127.0.0.1:<port> (the local API). Expo's
#      template normally sets it already; the patch makes it certain and logs it.
#   2. JS log levels. A Release build logs only errors from JS (RCTLog's release
#      threshold is "error") and writes no level next to the text, so console.warn
#      would be invisible to the gate. The patch lowers the threshold to "info" and
#      adds one RCTLog function that prints every warning and error with a marker:
#         [fitbud-gate] js.warn <message>     [fitbud-gate] native.error <message>
#      scan-logs.mjs fails the run on those markers. The default RN logging is kept.
#
#   3. Theme: UIUserInterfaceStyle = Automatic (app.json pins Light), so the app
#      follows `simctl ui appearance`. Harness-only; the shipped app follows the
#      system from Z12-57.
#
# Android
#   Theme: checked, and switched to a DayNight AppTheme parent only if prebuild wrote
#   a light-only one (patch_android_theme). Harness-only, as on iOS.
#   Cleartext to the local API only: a network security config that permits plain
#   HTTP to 10.0.2.2, 127.0.0.1 and localhost (the emulator's view of the runner)
#   and nothing else. A Release build targets SDK 34, where cleartext is off by
#   default; Expo enables it only in the debug manifest. JS console.warn/error
#   already reach logcat with their level (W/E ReactNativeJS), so no log patch.
set -euo pipefail
# shellcheck source=lib.sh
source "$(dirname "${BASH_SOURCE[0]}")/lib.sh"

PLATFORM="$(device_platform "${1:-}")"
NATIVE_DIR="${2:-}"
[ -n "$NATIVE_DIR" ] && [ -d "$NATIVE_DIR" ] || device_die "usage: patch-native.sh ios|android <generated native dir>"

GATE_MARKER="FitBud device gate (Z12-35)"
PLISTBUDDY="${PLISTBUDDY:-/usr/libexec/PlistBuddy}"

# The app target's directory is named after the Xcode project (the Live Activity
# target lives elsewhere), exactly as build-ios-sim.sh finds the scheme.
ios_app_dir() {
  local project
  project="$(find "$NATIVE_DIR" -maxdepth 1 -name '*.xcodeproj' -type d | sort | sed -n 1p)"
  [ -n "$project" ] || device_die "no .xcodeproj under $NATIVE_DIR."
  printf '%s/%s' "$NATIVE_DIR" "$(basename "$project" .xcodeproj)"
}

patch_ios_ats() {
  local plist before
  plist="$(ios_app_dir)/Info.plist"
  [ -f "$plist" ] || device_die "no app Info.plist at $plist."
  before="$("$PLISTBUDDY" -c 'Print :NSAppTransportSecurity:NSAllowsLocalNetworking' "$plist" 2>/dev/null || echo unset)"
  device_log "ATS NSAllowsLocalNetworking in the stock $(basename "$(dirname "$plist")")/Info.plist: $before"
  "$PLISTBUDDY" -c 'Add :NSAppTransportSecurity dict' "$plist" 2>/dev/null || true
  "$PLISTBUDDY" -c 'Add :NSAppTransportSecurity:NSAllowsLocalNetworking bool true' "$plist" 2>/dev/null \
    || "$PLISTBUDDY" -c 'Set :NSAppTransportSecurity:NSAllowsLocalNetworking true' "$plist"
  device_log "ATS NSAllowsLocalNetworking now: $("$PLISTBUDDY" -c 'Print :NSAppTransportSecurity:NSAllowsLocalNetworking' "$plist")"
}

patch_ios_logging() {
  local delegate
  delegate="$(ios_app_dir)/AppDelegate.mm"
  if [ ! -f "$delegate" ]; then
    # Expo SDK 52 generates AppDelegate.mm. A Swift AppDelegate (a later SDK) needs
    # its own patch; until then the gate still sees JS errors, not warnings.
    device_warn "no AppDelegate.mm under $NATIVE_DIR; JS warnings will not carry a level in the iOS log."
    return 0
  fi
  if grep -Fq "$GATE_MARKER" "$delegate"; then
    device_log "AppDelegate.mm already patched"
    return 0
  fi
  grep -Fq 'didFinishLaunchingWithOptions' "$delegate" || device_die "AppDelegate.mm has no didFinishLaunchingWithOptions; the log patch cannot be placed."
  GATE_MARKER="$GATE_MARKER" perl -0pi -e '
    my $m = $ENV{GATE_MARKER};
    s{(#import "AppDelegate\.h"\n)}{$1#import <React/RCTLog.h>\n};
    my $hook = <<"OBJC";
  // $m: log JS and native warnings and errors with their level, so the gate can
  // fail on them. Release builds otherwise drop warnings. Never in a shipped build:
  // this file is generated on the CI runner and discarded.
  RCTSetLogThreshold(RCTLogLevelInfo);
  RCTAddLogFunction(^(RCTLogLevel level, RCTLogSource source, NSString *fileName, NSNumber *lineNumber, NSString *message) {
    if (level < RCTLogLevelWarning) {
      return;
    }
    NSString *origin = source == RCTLogSourceJavaScript ? \@"js" : \@"native";
    NSString *kind = level >= RCTLogLevelError ? \@"error" : \@"warn";
    NSLog(\@"[fitbud-gate] %\@.%\@ %\@", origin, kind, message);
  });
OBJC
    s{(didFinishLaunchingWithOptions:\(NSDictionary \*\)launchOptions\s*\n?\{\n)}{$1$hook} or die "no didFinishLaunchingWithOptions body\n";
  ' "$delegate"
  grep -Fq "$GATE_MARKER" "$delegate" || device_die "the AppDelegate.mm log patch did not apply."
  grep -Fq '#import <React/RCTLog.h>' "$delegate" || device_die "AppDelegate.mm has no #import \"AppDelegate.h\" to anchor the RCTLog import."
  device_log "AppDelegate.mm: JS and native warnings/errors now log as [fitbud-gate] <origin>.<level>"
}

patch_android_cleartext() {
  local manifest="$NATIVE_DIR/app/src/main/AndroidManifest.xml"
  local xml_dir="$NATIVE_DIR/app/src/main/res/xml"
  local config="fitbud_device_gate_network"
  [ -f "$manifest" ] || device_die "no $manifest."
  device_log "stock main manifest: usesCleartextTraffic=$(grep -Eo 'android:usesCleartextTraffic="[a-z]+"' "$manifest" || echo unset), networkSecurityConfig=$(grep -Eo 'android:networkSecurityConfig="[^"]+"' "$manifest" || echo unset)"
  mkdir -p "$xml_dir"
  cat >"$xml_dir/$config.xml" <<'XML'
<?xml version="1.0" encoding="utf-8"?>
<!-- FitBud device gate (Z12-35): plain HTTP to the runner's local API only. Generated on CI, never shipped. -->
<network-security-config>
  <domain-config cleartextTrafficPermitted="true">
    <domain includeSubdomains="false">10.0.2.2</domain>
    <domain includeSubdomains="false">127.0.0.1</domain>
    <domain includeSubdomains="false">localhost</domain>
  </domain-config>
</network-security-config>
XML
  if grep -Fq "@xml/$config" "$manifest"; then
    device_log "manifest already points at @xml/$config"
    return 0
  fi
  if grep -Fq 'android:networkSecurityConfig=' "$manifest"; then
    device_die "the generated manifest already has a networkSecurityConfig; merge it by hand rather than overwrite it."
  fi
  perl -0pi -e 's{<application\b}{<application android:networkSecurityConfig="\@xml/fitbud_device_gate_network"}' "$manifest"
  grep -Fq "@xml/$config" "$manifest" || device_die "the manifest patch did not apply."
  device_log "manifest: networkSecurityConfig=@xml/$config (cleartext to 10.0.2.2, 127.0.0.1, localhost)"
}

# Theme (orchestrator decision, 14 Nov 2026). app.json sets userInterfaceStyle "light",
# which prebuild writes as UIUserInterfaceStyle=Light, so the iOS app ignores
# `simctl ui appearance dark` and the gate could not prove dark until Z12-57 changes
# the shipped config. Harness-only: the generated Info.plist follows the system.
patch_ios_theme() {
  local plist before
  plist="$(ios_app_dir)/Info.plist"
  before="$("$PLISTBUDDY" -c 'Print :UIUserInterfaceStyle' "$plist" 2>/dev/null || echo unset)"
  "$PLISTBUDDY" -c 'Set :UIUserInterfaceStyle Automatic' "$plist" 2>/dev/null \
    || "$PLISTBUDDY" -c 'Add :UIUserInterfaceStyle string Automatic' "$plist"
  device_log "UIUserInterfaceStyle: stock $before, now $("$PLISTBUDDY" -c 'Print :UIUserInterfaceStyle' "$plist") (harness-only; the shipped app follows the system from Z12-57)"
}

# Android: userInterfaceStyle needs expo-system-ui, which the app does not have, so
# prebuild writes nothing for it and React Native's Appearance follows the system
# uiMode (`cmd uimode night yes|no`). The one thing that could pin it light is a
# light-only AppCompat parent for AppTheme; if prebuild ever writes one, the
# generated styles.xml is switched to the DayNight parent. Harness-only, as on iOS.
patch_android_theme() {
  local styles="$NATIVE_DIR/app/src/main/res/values/styles.xml" parent
  if [ ! -f "$styles" ]; then
    device_warn "no $styles; the Android theme was not checked"
    return 0
  fi
  parent="$(sed -n 's/.*<style name="AppTheme" parent="\([^"]*\)".*/\1/p' "$styles" | sed -n 1p)"
  device_log "AppTheme parent in the generated styles.xml: ${parent:-unknown}"
  case "$parent" in
    Theme.AppCompat.Light.*)
      perl -0pi -e 's{(<style name="AppTheme" parent=")Theme\.AppCompat\.Light\.}{${1}Theme.AppCompat.DayNight.}' "$styles"
      device_log "AppTheme parent switched to $(sed -n 's/.*<style name="AppTheme" parent="\([^"]*\)".*/\1/p' "$styles" | sed -n 1p) (harness-only)"
      ;;
  esac
}

case "$PLATFORM" in
  ios)
    patch_ios_ats
    patch_ios_logging
    patch_ios_theme
    ;;
  android)
    patch_android_cleartext
    patch_android_theme
    ;;
esac
